def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []
    freq = {}
    first_index = {}
    first_spelling = {}
    for idx, w in enumerate(words):
        key = w.lower()
        if key not in freq:
            freq[key] = 1
            first_index[key] = idx
            first_spelling[key] = w
        else:
            freq[key] += 1
    items = []
    for key in freq:
        items.append((first_spelling[key], freq[key], first_index[key]))
    items.sort(key=lambda x: (-x[1], x[2]))
    return [(w, c) for w, c, _ in items[:k]]

