import json
import math

def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid = 0
    service_data = {}

    for line in lines:
        if line.strip() == "":
            continue
        try:
            obj = json.loads(line)
        except Exception:
            invalid += 1
            continue

        if not isinstance(obj, dict):
            invalid += 1
            continue

        if "service" not in obj or "latency_ms" not in obj or "status" not in obj:
            invalid += 1
            continue

        service = obj["service"]
        latency = obj["latency_ms"]
        status = obj["status"]

        if not isinstance(service, str):
            invalid += 1
            continue
        if isinstance(latency, bool) or not isinstance(latency, (int, float)):
            invalid += 1
            continue
        if isinstance(status, bool) or not isinstance(status, (int, float)):
            invalid += 1
            continue

        if service not in service_data:
            service_data[service] = {"latencies": [], "ok": 0}
        service_data[service]["latencies"].append(latency)
        if 200 <= status < 300:
            service_data[service]["ok"] += 1

    result = {"invalid": invalid}
    for svc in sorted(service_data.keys()):
        latencies = service_data[svc]["latencies"]
        n = len(latencies)
        ok = service_data[svc]["ok"]
        ok_rate = ok / n if n != 0 else 0.0
        if n == 0:
            p95 = None
        else:
            sorted_lat = sorted(latencies)
            idx = math.ceil(0.95 * n) - 1
            if idx < 0:
                idx = 0
            if idx >= n:
                idx = n - 1
            p95 = sorted_lat[idx]
        result[svc] = {"count": n, "ok_rate": ok_rate, "p95_latency_ms": p95}

    return result
