class _StreamingGroupSum:
    def __init__(self, rows):
        self._rows = rows
        self.invalid_count = 0
        self._result = None
        self._done = False

    def __iter__(self):
        if self._done:
            yield from self._result
            return
        sums = {}
        order = []
        invalid = 0
        for row in self._rows:
            try:
                if not isinstance(row, (list, tuple)):
                    invalid += 1
                    continue
                if len(row) != 3:
                    invalid += 1
                    continue
                _, key, value = row
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    invalid += 1
                    continue
                try:
                    if key in sums:
                        sums[key] += value
                    else:
                        sums[key] = value
                        order.append(key)
                except TypeError:
                    invalid += 1
                    continue
            except Exception:
                invalid += 1
                continue
        self.invalid_count = invalid
        self._result = [(k, sums[k]) for k in order]
        self._done = True
        yield from self._result

def streaming_group_sum(rows):
    return _StreamingGroupSum(rows)

import time

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be > 0")
    last_exc = None
    for i in range(attempts):
        try:
            return fn()
        except Exception as e:
            last_exc = e
            if not retry_if(e):
                raise
            if i == attempts - 1:
                raise
            delay = base_delay * (2 ** i)
            sleep(delay)
    raise last_exc

import copy

def apply_patch_ops(document: dict, operations) -> dict:
    if not isinstance(document, dict):
        raise TypeError("document must be a dict")
    new_doc = copy.deepcopy(document)
    if operations is None:
        return new_doc
    for item in operations:
        try:
            op, path, value = item
        except Exception:
            raise ValueError(f"invalid operation entry: {item}")
        if not isinstance(path, str) or not path:
            raise ValueError(f"invalid path: {path}")
        keys = path.split(".")
        if any(k == "" for k in keys):
            raise ValueError(f"invalid path: {path}")

        if op == "set":
            cur = new_doc
            for k in keys[:-1]:
                if k not in cur:
                    cur[k] = {}
                elif not isinstance(cur[k], dict):
                    raise TypeError(f"path conflict at '{k}': expected dict")
                cur = cur[k]
            cur[keys[-1]] = copy.deepcopy(value)

        elif op == "delete":
            cur = new_doc
            for k in keys[:-1]:
                if k not in cur or not isinstance(cur[k], dict):
                    cur = None
                    break
                cur = cur[k]
            if cur is not None and isinstance(cur, dict):
                cur.pop(keys[-1], None)

        elif op == "increment":
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("increment value must be int or float")
            cur = new_doc
            for k in keys[:-1]:
                if k not in cur or not isinstance(cur[k], dict):
                    raise KeyError(f"path not found: {path}")
                cur = cur[k]
            leaf = keys[-1]
            if leaf not in cur:
                raise KeyError(f"path not found: {path}")
            cur_val = cur[leaf]
            if isinstance(cur_val, bool) or not isinstance(cur_val, (int, float)):
                raise TypeError(f"target value at '{path}' is not numeric")
            cur[leaf] = cur_val + value

        else:
            raise ValueError(f"unsupported op: {op}")

    return new_doc

