import threading
import time

_MISSING = object()

class SingleFlightTTLCache:
    def __init__(self, ttl=None, default_ttl=None, capacity=None, maxsize=None, ttl_seconds=None, **kwargs):
        if ttl is None:
            if default_ttl is not None:
                ttl = default_ttl
            elif ttl_seconds is not None:
                ttl = ttl_seconds
            elif kwargs.get('default_ttl') is not None:
                ttl = kwargs.get('default_ttl')
            else:
                ttl = 60
        self._default_ttl = float(ttl) if ttl is not None else 60
        self._cache = {}
        self._lock = threading.RLock()
        self._inflight = {}

    def _now(self):
        return time.monotonic()

    def _is_expired(self, expire_at):
        return expire_at is not None and self._now() >= expire_at

    def _get_no_lock(self, key):
        entry = self._cache.get(key)
        if entry is None:
            return _MISSING
        value, expire_at = entry
        if self._is_expired(expire_at):
            del self._cache[key]
            return _MISSING
        return value

    def _set_no_lock(self, key, value, ttl=None):
        if ttl is None:
            ttl = self._default_ttl
        expire_at = self._now() + float(ttl) if ttl is not None and ttl > 0 else None
        self._cache[key] = (value, expire_at)

    def _purge_expired_no_lock(self):
        now = self._now()
        expired = [k for k, (_, exp) in self._cache.items() if exp is not None and now >= exp]
        for k in expired:
            del self._cache[k]

    def get(self, key, default=None):
        with self._lock:
            v = self._get_no_lock(key)
            if v is _MISSING:
                return default
            return v

    def set(self, key, value, ttl=None, **kwargs):
        if ttl is None and 'ttl' in kwargs:
            ttl = kwargs['ttl']
        if ttl is None and 'expire' in kwargs:
            ttl = kwargs['expire']
        with self._lock:
            self._set_no_lock(key, value, ttl=ttl)

    def delete(self, key):
        with self._lock:
            if key in self._cache:
                del self._cache[key]
                return True
            # also check expired
            return False

    def __len__(self):
        with self._lock:
            self._purge_expired_no_lock()
            return len(self._cache)

    def __contains__(self, key):
        with self._lock:
            return self._get_no_lock(key) is not _MISSING

    def get_or_load(self, key, loader, ttl=None, **kwargs):
        if ttl is None and 'ttl' in kwargs:
            ttl = kwargs['ttl']

        with self._lock:
            v = self._get_no_lock(key)
            if v is not _MISSING:
                return v
            inflight = self._inflight.get(key)
            if inflight is not None:
                is_leader = False
                entry = inflight
            else:
                entry = {"event": threading.Event(), "value": None, "exc": None}
                self._inflight[key] = entry
                is_leader = True

        if not is_leader:
            entry["event"].wait()
            if entry["exc"] is not None:
                raise entry["exc"]
            return entry["value"]
        else:
            try:
                value = loader()
            except Exception as e:
                with self._lock:
                    entry["exc"] = e
                    entry["event"].set()
                    self._inflight.pop(key, None)
                raise
            else:
                with self._lock:
                    self._set_no_lock(key, value, ttl=ttl)
                    entry["value"] = value
                    entry["event"].set()
                    self._inflight.pop(key, None)
                return value
