import threading
from collections import deque

class BoundedQueue:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be > 0")
        self._q = deque()
        self._cap = capacity
        self._closed = False
        self._cond = threading.Condition(threading.Lock())

    def put(self, item):
        with self._cond:
            if self._closed:
                raise RuntimeError("queue is closed")
            while len(self._q) >= self._cap:
                if self._closed:
                    raise RuntimeError("queue is closed")
                self._cond.wait()
                if self._closed:
                    raise RuntimeError("queue is closed")
            if self._closed:
                raise RuntimeError("queue is closed")
            self._q.append(item)
            self._cond.notify_all()

    def get(self):
        with self._cond:
            while len(self._q) == 0:
                if self._closed:
                    raise RuntimeError("queue is closed")
                self._cond.wait()
            item = self._q.popleft()
            self._cond.notify_all()
            return item

    def close(self):
        with self._cond:
            if self._closed:
                return
            self._closed = True
            self._cond.notify_all()
